   23      pub fn install() -> Result<Self, ctrlc::Error> {
   24          let this = Self {
   25              phase: Arc::new(AtomicU8::new(LOADING)),
   26              armed: Arc::new(AtomicBool::new(false)),
   27              cancel: Arc::new(AtomicBool::new(false)),
